eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   track: () => (/* binding */ track)\n/* harmony export */ });\n/* __next_internal_client_entry_do_not_use__ track auto */ function track(event, params = {}) {\n    if (true) return;\n    window.dataLayer = window.dataLayer || [];\n    const url = new URL(window.location.href);\n    window.dataLayer.push({\n        event,\n        page: params.page ?? url.pathname,\n        source: params.source ?? url.searchParams.get(\"utm_source\") ?? undefined,\n        campaign: params.campaign ?? url.searchParams.get(\"utm_campaign\") ?? undefined,\n        ...params\n    });\n}\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(ssr)/./lib/analytics.ts\n");

