eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   NAV: () => (/* binding */ NAV),\n/* harmony export */   PRIMARY_CTA: () => (/* binding */ PRIMARY_CTA)\n/* harmony export */ });\n/* harmony import */ var _services__WEBPACK_IMPORTED_MODULE_0__ = __webpack_require__(/*! ./services */ \"(ssr)/./lib/services.ts\");\n/* harmony import */ var _site__WEBPACK_IMPORTED_MODULE_1__ = __webpack_require__(/*! ./site */ \"(ssr)/./lib/site.ts\");\n\n\n/**\n * Phase 1 navigation (spec section 24).\n *\n * Land Investment and Rentals are deliberately absent: both are discontinued and\n * must not appear in the header, footer, sitemap or any internal link.\n * Compliance and technology services are intentionally not top-level items.\n */ const NAV = [\n    {\n        name: \"About\",\n        href: \"/about/\",\n        links: [\n            {\n                name: \"About Raulji Group\",\n                href: \"/about/\",\n                description: \"Who we are and how we work\"\n            },\n            {\n                name: \"Our Team\",\n                href: \"/team/\",\n                description: \"The people handling your registration\"\n            }\n        ]\n    },\n    {\n        name: \"Business Registration\",\n        href: \"/services/\",\n        links: _services__WEBPACK_IMPORTED_MODULE_0__.SERVICES.map((s)=>({\n                name: s.shortName === \"Private Limited\" ? \"Private Limited Company\" : s.name.replace(\" Registration\", \"\"),\n                href: s.path,\n                description: s.cardBlurb\n            })),\n        feature: {\n            title: \"Not sure which structure fits?\",\n            body: \"Compare all four side by side on liability, compliance, tax and funding before you commit.\",\n            href: \"/compare/\",\n            cta: \"Compare structures\"\n        }\n    },\n    {\n        name: \"Gujarat\",\n        href: \"/gujarat/\",\n        links: [\n            {\n                name: \"Business Registration Across Gujarat\",\n                href: \"/gujarat/\",\n                description: \"Coverage across all 33 districts\"\n            },\n            {\n                name: \"Major Cities\",\n                href: \"/gujarat/#cities\",\n                description: \"Find your local market\"\n            }\n        ]\n    },\n    {\n        name: \"Resources\",\n        links: [\n            {\n                name: \"Blog\",\n                href: \"/blog/\",\n                description: \"Notes on registration and running a business\"\n            },\n            {\n                name: \"Compare Business Structures\",\n                href: \"/compare/\",\n                description: \"Pvt Ltd vs LLP vs Partnership vs Proprietorship\"\n            },\n            {\n                name: \"FAQs\",\n                href: \"/faqs/\",\n                description: \"Answers to the questions we are asked most\"\n            }\n        ]\n    },\n    {\n        name: \"Technology & AI\",\n        links: [\n            {\n                name: \"Explore Raulji Technologies\",\n                href: _site__WEBPACK_IMPORTED_MODULE_1__.SITE.technologies,\n                description: \"Software, AI and digital transformation, on our technology brand\",\n                external: true\n            }\n        ]\n    }\n];\nconst PRIMARY_CTA = {\n    name: \"Start Your Business\",\n    href: \"/contact/\"\n};\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(ssr)/./lib/nav.ts\n");

